steps.action:
curl -s https://api.linear.app/graphql -H "Content-Type: application/json" -H "Authorization: Bearer <TOKEN>" -d '{
  "query": "{
    teams(name: \"Web\") {
      nodes {
        id
        name
        cycles(state: \"current\") {
          nodes {
            id
            name
            endsAt
            issues(first: 50) {
              nodes {
                id
                identifier
                title
                estimate
                assignee {
                  id
                  name
                }
              }
            }
          }
        }
      }
    }
    users(name: \"Maya Chen\") {
      nodes {
        id
        name
      }
    }
  }
}'
